insert into public.bai_hoc (id, khoi, chuong, tieu_de, mo_ta, tien_to, tab_cu, thu_tu) values
  ('tap-hop', 6, 'Chương I: Tập hợp các số tự nhiên', 'Bài 1. Tập hợp', 'Tập hợp và phần tử, kí hiệu ∈ và ∉, liệt kê và nêu dấu hiệu đặc trưng, tập ℕ và ℕ*, đếm phần tử.', 'TH6-', '6 - Tập hợp', 10),
  ('cach-ghi-so-tu-nhien', 6, 'Chương I: Tập hợp các số tự nhiên', 'Bài 2. Cách ghi số tự nhiên', 'Hệ thập phân, đọc và viết số, giá trị các chữ số, số La Mã từ 1 đến 30, lập số từ các chữ số.', 'GS6-', '6 - Cách ghi số tự nhiên', 20),
  ('thu-tu-trong-tap-hop-so-tu-nhien', 6, 'Chương I: Tập hợp các số tự nhiên', 'Bài 3. Thứ tự trong tập hợp các số tự nhiên', 'Tia số, so sánh hai số tự nhiên, số liền trước và số liền sau, kí hiệu ≤ và ≥, tính chất bắc cầu.', 'TT6-', '6 - Thứ tự trong tập hợp các số tự nhiên', 30),
  ('phep-cong-va-phep-tru-so-tu-nhien', 6, 'Chương I: Tập hợp các số tự nhiên', 'Bài 4. Phép cộng và phép trừ số tự nhiên', 'Số hạng, tổng, số bị trừ, số trừ, hiệu; tính chất giao hoán, kết hợp; tính nhẩm, tính hợp lí; tìm số chưa biết.', 'CT6-', '6 - Phép cộng và phép trừ số tự nhiên', 40),
  ('phep-nhan-va-phep-chia-so-tu-nhien', 6, 'Chương I: Tập hợp các số tự nhiên', 'Bài 5. Phép nhân và phép chia số tự nhiên', 'Thừa số, tích; tính chất giao hoán, kết hợp, phân phối; tính nhẩm; phép chia hết, phép chia có dư; tìm số chưa biết.', 'NC6-', '6 - Phép nhân và phép chia số tự nhiên', 50),
  ('luy-thua-voi-so-mu-tu-nhien', 6, 'Chương I: Tập hợp các số tự nhiên', 'Bài 6. Luỹ thừa với số mũ tự nhiên', 'Cơ số, số mũ; bình phương, lập phương; luỹ thừa của 10; nhân và chia hai luỹ thừa cùng cơ số.', 'LU6-', '6 - Luỹ thừa với số mũ tự nhiên', 60),
  ('thu-tu-thuc-hien-cac-phep-tinh', 6, 'Chương I: Tập hợp các số tự nhiên', 'Bài 7. Thứ tự thực hiện các phép tính', 'Biểu thức không có và có dấu ngoặc, biểu thức chứa chữ, lập biểu thức cho bài toán thực tế; ôn trộn cả Chương I.', 'PT6-', '6 - Thứ tự thực hiện các phép tính', 70),
  ('bai-tap-cuoi-chuong-1-toan-6', 6, 'Chương I: Tập hợp các số tự nhiên', 'Bài tập cuối chương I', 'Ôn tập cả chương (SGK trang 27–28): tập hợp, ghi số, thứ tự, cộng trừ nhân chia, luỹ thừa, thứ tự thực hiện các phép tính, bài toán thực tế.', 'CC1-', '6 - Bài tập cuối chương I', 80),
  ('quan-he-chia-het-va-tinh-chat', 6, 'Chương II: Tính chia hết trong tập hợp các số tự nhiên', 'Bài 8. Quan hệ chia hết và tính chất', 'Kí hiệu chia hết, ước và bội, cách tìm ước và bội, tính chất chia hết của một tổng, một hiệu.', 'QH6-', '6 - Quan hệ chia hết và tính chất', 90),
  ('dau-hieu-chia-het', 6, 'Chương II: Tính chia hết trong tập hợp các số tự nhiên', 'Bài 9. Dấu hiệu chia hết', 'Dấu hiệu chia hết cho 2, 5, 9, 3; thay dấu * bởi chữ số; tổng, hiệu, chia nhóm, trồng cây.', 'DH6-', '6 - Dấu hiệu chia hết', 100),
  ('so-nguyen-to', 6, 'Chương II: Tính chia hết trong tập hợp các số tự nhiên', 'Bài 10. Số nguyên tố', 'Số nguyên tố, hợp số; phân tích ra thừa số nguyên tố theo sơ đồ cây, sơ đồ cột; ước nguyên tố, chia nhóm, xếp hàng.', 'NT6-', '6 - Số nguyên tố', 110),
  ('luyen-tap-chung-sau-bai-10', 6, 'Chương II: Tính chia hết trong tập hợp các số tự nhiên', 'Luyện tập chung (sau Bài 10)', 'SGK trang 43: kết hợp tính chất chia hết, dấu hiệu chia hết, số nguyên tố, phân tích ra thừa số nguyên tố; bài toán thực tế.', 'LC2-', '6 - Luyện tập chung (sau Bài 10)', 120),
  ('uoc-chung-lon-nhat', 6, 'Chương II: Tính chia hết trong tập hợp các số tự nhiên', 'Bài 11. Ước chung. Ước chung lớn nhất', 'Ước chung, tìm ƯCLN bằng phân tích ra thừa số nguyên tố, phân số tối giản, bài toán chia đều.', 'UC6-', '6 - Ước chung. Ước chung lớn nhất', 130),
  ('boi-chung-nho-nhat', 6, 'Chương II: Tính chia hết trong tập hợp các số tự nhiên', 'Bài 12. Bội chung, bội chung nhỏ nhất', 'Bội chung, tìm BCNN bằng phân tích ra thừa số nguyên tố, suy ra bội chung, bài toán thực tế.', 'BC6-', '6 - Bội chung, bội chung nhỏ nhất', 140),
  ('luyen-tap-chung-sau-bai-12', 6, 'Chương II: Tính chia hết trong tập hợp các số tự nhiên', 'Luyện tập chung (sau Bài 12)', 'SGK trang 54, 55: ƯCLN và BCNN, ƯCLN · BCNN = a · b, rút gọn và quy đồng mẫu phân số, chạy vòng sân, bánh răng, lịch can chi.', 'LC3-', '6 - Luyện tập chung (sau Bài 12)', 150),
  ('bai-tap-cuoi-chuong-2-toan-6', 6, 'Chương II: Tính chia hết trong tập hợp các số tự nhiên', 'Bài tập cuối chương II', 'SGK trang 56: ôn cả chương, chia hết, số nguyên tố, ƯCLN và BCNN, tìm số mũ, bài toán cổ đàn vịt, lịch bảo dưỡng xe.', 'CC2-', '6 - Bài tập cuối chương II', 160),
  ('tap-hop-so-nguyen', 6, 'Chương III: Số nguyên', 'Bài 13. Tập hợp các số nguyên', 'Số nguyên âm và tập hợp ℤ, số nguyên trong thực tế, trục số, so sánh hai số nguyên.', 'SN6-', '6 - Tập hợp các số nguyên', 170),
  ('phep-cong-tru-so-nguyen', 6, 'Chương III: Số nguyên', 'Bài 14. Phép cộng và phép trừ số nguyên', 'Cộng hai số nguyên, tính chất của phép cộng, trừ hai số nguyên, bài toán thực tế.', 'PC6-', '6 - Phép cộng và phép trừ số nguyên', 180),
  ('quy-tac-dau-ngoac', 6, 'Chương III: Số nguyên', 'Bài 15. Quy tắc dấu ngoặc', 'Viết gọn một tổng, bỏ dấu ngoặc, đặt dấu ngoặc và đổi chỗ số hạng, tính hợp lí, bài toán thực tế.', 'DN6-', '6 - Quy tắc dấu ngoặc', 190),
  ('luyen-tap-chung-so-nguyen', 6, 'Chương III: Số nguyên', 'Luyện tập chung (sau Bài 15)', 'SGK trang 69: số nguyên và tập hợp ℤ, ngoặc tròn và ngoặc vuông, tính hợp lí, bài toán thực tế.', 'LT6-', '6 - Luyện tập chung (Chương III)', 200),
  ('phep-nhan-so-nguyen', 6, 'Chương III: Số nguyên', 'Bài 16. Phép nhân số nguyên', 'Nhân hai số nguyên khác dấu, cùng dấu, tính chất của phép nhân, tính hợp lí, so sánh tích, bài toán thực tế.', 'NH6-', '6 - Phép nhân số nguyên', 210),
  ('phep-chia-het-uoc-boi', 6, 'Chương III: Số nguyên', 'Bài 17. Phép chia hết. Ước và bội của một số nguyên', 'Phép chia hết, dấu của thương, tìm ước và bội, ước chung, tìm x và n, bài toán thực tế.', 'UB6-', '6 - Phép chia hết, ước và bội', 220),
  ('luyen-tap-chung-sau-bai-17', 6, 'Chương III: Số nguyên', 'Luyện tập chung (sau Bài 17)', 'SGK trang 75: nhân, chia số nguyên, tính hợp lí, giá trị biểu thức, ước và bội, bài toán thực tế.', 'LC6-', '6 - Luyện tập chung (sau Bài 17)', 230),
  ('bai-tap-cuoi-chuong-3', 6, 'Chương III: Số nguyên', 'Bài tập cuối chương III', 'Ôn tập cả chương (SGK trang 76): số nguyên, so sánh, tập hợp ℤ, cộng trừ, quy tắc dấu ngoặc, nhân chia, ước và bội, bài toán thực tế.', 'CC3-', '6 - Bài tập cuối chương III', 240),
  ('tap-hop-so-huu-ti', 7, 'Chương I: Số hữu tỉ', 'Bài 1. Tập hợp các số hữu tỉ', 'Số hữu tỉ, biểu diễn trên trục số, số đối và so sánh hai số hữu tỉ.', 'SH7-', '7 - Tập hợp các số hữu tỉ', 250),
  ('cong-tru-nhan-chia-so-huu-ti', 7, 'Chương I: Số hữu tỉ', 'Bài 2. Cộng, trừ, nhân, chia số hữu tỉ', 'Cộng, trừ, nhân, chia số hữu tỉ, quy tắc dấu ngoặc và tính một cách hợp lí.', 'CT7-', '7 - Cộng, trừ, nhân, chia số hữu tỉ', 260),
  ('luy-thua-so-huu-ti', 7, 'Chương I: Số hữu tỉ', 'Bài 3. Luỹ thừa với số mũ tự nhiên của một số hữu tỉ', 'Luỹ thừa, luỹ thừa của tích và thương, nhân chia luỹ thừa cùng cơ số, luỹ thừa của luỹ thừa.', 'LT7-', '7 - Luỹ thừa của số hữu tỉ', 270),
  ('thu-tu-phep-tinh-chuyen-ve', 7, 'Chương I: Số hữu tỉ', 'Bài 4. Thứ tự thực hiện các phép tính. Quy tắc chuyển vế', 'Thứ tự thực hiện phép tính có và không có dấu ngoặc, đẳng thức, quy tắc chuyển vế và tìm x.', 'TC7-', '7 - Thứ tự phép tính và quy tắc chuyển vế', 280),
  ('bai-tap-cuoi-chuong-1-toan-7', 7, 'Chương I: Số hữu tỉ', 'Bài tập cuối chương I', 'Ôn tập cả Chương I: số hữu tỉ và so sánh, cộng trừ nhân chia, luỹ thừa, quy tắc dấu ngoặc và chuyển vế, tìm x.', 'CC7-', '7 - Bài tập cuối chương I', 290),
  ('so-thap-phan-vo-han-tuan-hoan', 7, 'Chương II: Số thực', 'Bài 5. Làm quen với số thập phân vô hạn tuần hoàn', 'Số thập phân hữu hạn và vô hạn tuần hoàn, chu kì, viết phân số dưới dạng số thập phân, làm tròn số và độ chính xác.', 'TP7-', '7 - Số thập phân vô hạn tuần hoàn', 300),
  ('so-vo-ti-can-bac-hai', 7, 'Chương II: Số thực', 'Bài 6. Số vô tỉ. Căn bậc hai số học', 'Số vô tỉ, căn bậc hai số học, tính căn bằng máy tính và làm tròn, cạnh hình vuông và đường chéo hình chữ nhật.', 'VT7-', '7 - Số vô tỉ và căn bậc hai số học', 310),
  ('tap-hop-so-thuc', 7, 'Chương II: Số thực', 'Bài 7. Tập hợp các số thực', 'Số thực và tập ℝ, biểu diễn số thực trên trục số, so sánh hai số thực, giá trị tuyệt đối của một số thực.', 'ST7-', '7 - Tập hợp các số thực', 320),
  ('bai-tap-cuoi-chuong-2-toan-7', 7, 'Chương II: Số thực', 'Bài tập cuối chương II', 'Ôn tập Chương II (Số thực): số thập phân vô hạn tuần hoàn, số vô tỉ và căn bậc hai, số thực, so sánh và giá trị tuyệt đối.', 'C27-', '7 - Bài tập cuối chương II', 330),
  ('tam-giac-bang-nhau', 7, 'Chương IV: Tam giác bằng nhau', 'Bài 13, 14. Tam giác bằng nhau', 'Hai tam giác bằng nhau và ba trường hợp bằng nhau: c.c.c, c.g.c, g.c.g.', 'TG7-', '7 - Tam giác bằng nhau', 340),
  ('tam-giac-vuong-bang-nhau', 7, 'Chương IV: Tam giác bằng nhau', 'Bài 15. Các trường hợp bằng nhau của tam giác vuông', 'Hai cạnh góc vuông, cạnh góc vuông – góc nhọn kề, cạnh huyền – góc nhọn, cạnh huyền – cạnh góc vuông.', 'TV7-', '7 - Tam giác vuông bằng nhau', 350),
  ('thu-thap-phan-loai-du-lieu', 7, 'Chương V: Thu thập và biểu diễn dữ liệu', 'Bài 17. Thu thập và phân loại dữ liệu', 'Dữ liệu là số và không là số, thu thập dữ liệu, bảng thống kê, tính đại diện của dữ liệu.', 'DL7-', '7 - Thu thập và phân loại dữ liệu', 360)
